return async function(config, file, ctx) { 
  // 1. Convert file to Blob
  const blob = await (await fetch(file.data)).blob();

  // 2. Prepare FormData
  const fd = new FormData();
  fd.append('file', blob, file.name);
  fd.append('token', config.token);
  if (config.albumId) fd.append('album_id', config.albumId);

  // 3. Send Request
  // ctx.fetch is a sandboxed fetch wrapper
  const res = await ctx.fetch('https://api.example.com/upload', {
    method: 'POST',
    body: fd
  });

  // 4. Handle Response
  if (!res.ok) throw new Error('HTTP ' + res.status);
  const data = res.body;

  if (!data.success) throw new Error(data.message || 'Upload failed');

  // 5. Return URL
  return data.url;
}
